/*
 * os/test/test_os_data.c - the STACK segment block OS_$STACK (source-4k71)
 *
 * Generated by: Claude Opus 5.5
 *
 * Pins the layout of map "D EB0000 STACK size = 2C00" as os/os.h declares
 * it: the map's labels (NULL_STACK_GUARD, NULL_STACK, NULL_PC,
 * P1_STACK_GUARD, INT_STACK_GUARD / P1_STACK_BASE, INT_STACK_BASE), the
 * interrupt stack's initial SP 0xEB2BE8 and IO_$SAVED_INT_SR 0xEB2BF8 that
 * io/sau2/use_int_stack.s and proc1/sau2/int_handler.s reach as
 * `OS_$STACK + off', the page alignment OS_$INIT's guard-page frees rely on,
 * and the zero contents (the image carries no bytes for the segment).
 */

#include <stdio.h>
#include <stdint.h>
#include <string.h>

static int tests_passed = 0;
static int tests_failed = 0;

#define RUN_TEST(name) do { \
    printf("  Running %s... ", #name); \
    test_##name(); \
    printf("PASSED\n"); \
    tests_passed++; \
} while (0)

#define ASSERT_EQ(expected, actual) do { \
    if ((unsigned long)(expected) != (unsigned long)(actual)) { \
        printf("FAILED\n    Expected: 0x%lx, Got: 0x%lx at line %d\n", \
               (unsigned long)(expected), (unsigned long)(actual), __LINE__); \
        tests_failed++; \
        return; \
    } \
} while (0)

#include "os/os_internal.h"
#include "io/io.h"
#include "../os_data.c"

/* Lay the target VA space over the block at its image address. */
static void at_image_address(void)
{
    ARCH_HOST_VA_BASE = (uintptr_t)&OS_$STACK - 0x00EB0000u;
}

static uint32_t va(const void *p)
{
    return ARCH_PTR_TO_VA(p);
}

static void test_segment_size_and_address(void)
{
    ASSERT_EQ(0x2C00, sizeof(os_$stack_t));
    ASSERT_EQ(OS_$STACK_SIZE, sizeof(OS_$STACK));
    ASSERT_EQ(0x00EB0000u, MODULE_DATA_ADDR(OS_$STACK));
}

/* OS_$INIT frees 0xEB0000 / 0xEB0800 / 0xEB2000 as 1 KB pages, so the type
 * carries page alignment (the m68k object's section is 2**10; the host
 * MODULE_DATA definition sets its own alignment, so only the type is
 * checked here). */
static void test_page_aligned(void)
{
    ASSERT_EQ(0x400, _Alignof(os_$stack_t));
}

static void test_map_labels(void)
{
    at_image_address();
    ASSERT_EQ(0x00EB0000u, va(NULL_STACK_GUARD));
    ASSERT_EQ(0x00EB07F4u, va(OS_$STACK.null_stack));
    ASSERT_EQ(0x00EB07FCu, va(&NULL_PC));
    ASSERT_EQ(0x00EB0800u, va(P1_STACK_GUARD));
    ASSERT_EQ(0x00EB2000u, va(INT_STACK_GUARD));
    ASSERT_EQ(0x00EB2000u, va(P1_STACK_BASE));
    ASSERT_EQ(0x00EB2C00u, va(INT_STACK_BASE));
    ARCH_HOST_VA_BASE = 0;
}

/* The two cells the hand-written assembly reaches by alias. */
static void test_int_stack_cells(void)
{
    at_image_address();
    ASSERT_EQ(0x00EB2BE8u, va(OS_$STACK.int_stack_top));
    ASSERT_EQ(0x00EB2BE8u, va((char *)&OS_$STACK + OS_$STACK_INT_SP_OFF));
    ASSERT_EQ(0x00EB2BF8u, va(&IO_$SAVED_INT_SR));
    ASSERT_EQ(0x18, INT_STACK_BASE - (char *)OS_$STACK.int_stack_top);
    ARCH_HOST_VA_BASE = 0;
}

/* The 0x400 bytes OS_$INIT clears below INT_STACK_BASE are the top page of
 * the interrupt stack, above its guard page. */
static void test_int_stack_page(void)
{
    ASSERT_EQ(0x2800, (INT_STACK_BASE - 0x400) - (char *)&OS_$STACK);
    ASSERT_EQ(0x2400, (char *)OS_$STACK.int_stack - (char *)&OS_$STACK);
}

static void test_zero_filled(void)
{
    const uint8_t *p = (const uint8_t *)&OS_$STACK;
    size_t i;
    for (i = 0; i < sizeof(OS_$STACK); i++) {
        ASSERT_EQ(0, p[i]);
    }
}

/* IO_$SAVED_INT_SR and NULL_PC are the block's fields, not other objects. */
static void test_field_aliases(void)
{
    IO_$SAVED_INT_SR = 0x2704;
    ASSERT_EQ(0x2704, OS_$STACK.saved_int_sr);
    NULL_PC = 0x00E24C60u;
    ASSERT_EQ(0x00E24C60u, OS_$STACK.null_pc);
    IO_$SAVED_INT_SR = 0;
    NULL_PC = 0;
}

int main(void)
{
    printf("OS_$STACK tests:\n");
    RUN_TEST(segment_size_and_address);
    RUN_TEST(page_aligned);
    RUN_TEST(map_labels);
    RUN_TEST(int_stack_cells);
    RUN_TEST(int_stack_page);
    RUN_TEST(zero_filled);
    RUN_TEST(field_aliases);
    printf("\n%d passed, %d failed\n", tests_passed, tests_failed);
    return tests_failed != 0;
}
